	private String truncateItemName(String name, int maxChars)
	{
		name = name.replaceAll("\\s*\\(Members\\)", "")
			.replaceAll("\\s*\\(members\\)", "")
			.trim();
		if (name.length() <= maxChars) return name;
		return name.substring(0, maxChars - 1) + "…";
	}

